const softDeletePerspectivesByAuthor = `-- name: SoftDeletePerspectivesByAuthor :many
WITH deleted AS (
    UPDATE perspectives
    SET deleted_at = now(), updated_at = now()
    WHERE author_id = $1 AND deleted_at IS NULL
    RETURNING arc_id
)
SELECT DISTINCT arc_id::uuid AS arc_id
FROM deleted
WHERE arc_id IS NOT NULL
`

// Soft-deletes every live perspective, draft or published, and returns the
// distinct arcs the published ones sat in.
func (q *Queries) SoftDeletePerspectivesByAuthor(ctx context.Context, authorID uuid.UUID) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, softDeletePerspectivesByAuthor, authorID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []uuid.UUID
	for rows.Next() {
		var arc_id uuid.UUID
		if err := rows.Scan(&arc_id); err != nil {
			return nil, err
		}
		items = append(items, arc_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

